    /**
     * Tests getting all ServiceProviders.
     *
     * @return    Collection
     */
    public List<ServiceProvider> testGetAll() throws Throwable {
    LOGGER.info( "ServiceProviderTest:testGetAll() - Retrieving Collection of ServiceProviders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ServiceProvider : " );
    List<ServiceProvider> collection  = null;

    try {
        // call the static get method on the ServiceProviderService
        collection = service.getAllServiceProvider();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ServiceProvider currEntity  = null;
            Iterator<ServiceProvider> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getServiceProviderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

